package com.yisy.modules.doramcu.ai;

import com.yisy.modules.doramcu.hex.Hex3D;

/**
 * Represents an insight generated by a station's AI Core.
 * <p>
 * Insights provide actionable information about station operations, threats,
 * bonuses, and optimizations based on the station type and AI Core level.
 * </p>
 */
public class StationAiInsight {

    /**
     * Types of insights a station AI Core can generate.
     */
    public enum InsightType {
        /** Enemy fleet detected near the station */
        THREAT_DETECTED,
        /** Defense bonus applied to stationed fleets */
        DEFENSE_BONUS,
        /** Research points generated */
        RESEARCH_OUTPUT,
        /** Trade efficiency optimization */
        ECONOMIC_OPTIMIZATION,
        /** Mining output increase */
        RESOURCE_EXTRACTION,
        /** Assembly speed bonus */
        PRODUCTION_SCHEDULING,
        /** Colony growth bonus */
        COLONY_MANAGEMENT
    }

    private final InsightType type;
    private final String description;
    private final Hex3D position;

    /**
     * Creates a new station AI insight.
     *
     * @param type the type of insight
     * @param description human-readable description of the insight
     * @param position the hex position where the insight applies
     */
    public StationAiInsight(InsightType type, String description, Hex3D position) {
        this.type = type;
        this.description = description;
        this.position = position;
    }

    // --- Accessors ---

    public InsightType getType() {
        return type;
    }

    public String getDescription() {
        return description;
    }

    public Hex3D getPosition() {
        return position;
    }

    @Override
    public String toString() {
        return "StationAiInsight{" +
                "type=" + type +
                ", description='" + description + '\'' +
                ", position=" + position +
                '}';
    }
}
